static unsigned rows_five(uint64_t availability, unsigned column) {
    const uint64_t keep = UINT64_C(0x1001001001001);
#ifdef TZ_REINAS_CINCO_BMI2
    return (unsigned)_pext_u64(availability, keep << column);
#else
    return (unsigned)((((availability >> column) & keep) * UINT64_C(0x1002004008010)) >> 48) & 31;
#endif
}

static unsigned closed_five(uint32_t columns, uint32_t left, uint32_t right) {
    uint32_t first = columns & ~(left | right);
    if (!first) return 0;
    uint64_t available = first;
    for (unsigned row = 1; row < 5; ++row) {
        uint32_t mask = columns & ~((left << row) | (right >> row));
        if (!mask) return 0;
        available |= (uint64_t)mask << (12 * row);
    }
    unsigned a = __builtin_ctz(columns);
    unsigned previous = a, gap = 0;
    uint64_t low = five[2 * rows_five(available, a)], high = five[2 * rows_five(available, a) + 1];
    columns &= columns - 1;
    for (unsigned col = 1; col < 5; ++col) {
        a = __builtin_ctz(columns);
        columns &= columns - 1;
        unsigned distance = a - previous;
        gap = 5 * gap + (distance < 5 ? distance : 5) - 1;
        previous = a;
        unsigned index = 2 * (32 * col + rows_five(available, a));
        low &= five[index];
        high &= five[index + 1];
    }
    return (unsigned)(__builtin_popcountll(low & five[320 + 2 * gap]) +
                      __builtin_popcountll(high & five[321 + 2 * gap]));
}
